<?php include 'db.php'; require_role('Doctor'); $id=intval($_GET['id']); $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $stmt=$conn->prepare("INSERT INTO RADIOLOGY_REPORT(Report_Date,Findings,Diagnosis,Appointment_ID) VALUES(CURDATE(),?,?,?) ON DUPLICATE KEY UPDATE Findings=VALUES(Findings), Diagnosis=VALUES(Diagnosis), Report_Date=CURDATE()"); $stmt->bind_param('ssi',$_POST['findings'],$_POST['diagnosis'],$id); $stmt->execute(); $rid=$conn->insert_id; if($rid==0){ $r=$conn->query("SELECT Report_ID FROM RADIOLOGY_REPORT WHERE Appointment_ID=$id")->fetch_assoc(); $rid=$r['Report_ID']; } if(!empty($_POST['medication'])){ $stmt=$conn->prepare("INSERT INTO MEDICATION(Medication_Name,Dose,Start_Date,End_Date,Directions,Report_ID) VALUES(?,?,?,?,?,?)"); $stmt->bind_param('sssssi',$_POST['medication'],$_POST['dose'],$_POST['start'],$_POST['end'],$_POST['directions'],$rid); $stmt->execute(); } $msg='Report saved successfully'; } $page_title='Add Report'; include 'header.php'; ?>
<h2>Write Radiology Report</h2><?php if($msg) echo '<div class="alert">'.esc($msg).'</div>'; ?><form class="form" method="post"><textarea name="findings" placeholder="Findings" required></textarea><textarea name="diagnosis" placeholder="Diagnosis" required></textarea><h3>Medication Recommendation</h3><input name="medication" placeholder="Medication Name"><input name="dose" placeholder="Dose"><div class="grid2"><input name="start" type="date"><input name="end" type="date"></div><input name="directions" placeholder="Directions"><button>Save Report</button></form><?php include 'footer.php'; ?>